package com.pcguard.controller;
import com.pcguard.dto.AgentDtos.*; import com.pcguard.service.MonitoringService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/agents") public class AgentController { private final MonitoringService service; public AgentController(MonitoringService s){service=s;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@Valid @RequestBody Registration r){var c=service.register(r);return Map.of("success",true,"computerId",c.id,"status","REGISTERED","serverTime",Instant.now().toString());} @PostMapping("/{agentId}/heartbeat") @ResponseStatus(HttpStatus.NO_CONTENT) public void heartbeat(@PathVariable String agentId,@RequestBody HeartbeatRequest r,HttpServletRequest request){service.heartbeat(agentId,r,request.getRemoteAddr());} @PostMapping("/{agentId}/telemetry") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,Object> telemetry(@PathVariable String agentId,@RequestBody TelemetryRequest r){var t=service.submit(agentId,r);return service.view(t);} }
